import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { Field, FieldItem, FieldLabel } from "@/registry/erbium/ui/field";
import { RadioGroup, RadioGroupItem } from "@/registry/erbium/ui/radio-group";
import { useState } from "react";

const options = [
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
  { value: "system", label: "System" },
];

export default function RadioGroupControlled() {
  const [value, setValue] = useState("system");

  return (
    <div className="flex flex-col gap-4">
      <Field>
        <RadioGroup value={value} onValueChange={setValue}>
          {options.map((option) => (
            <FieldItem orientation="horizontal" key={option.value}>
              <RadioGroupItem value={option.value} />
              <FieldLabel>{option.label}</FieldLabel>
            </FieldItem>
          ))}
        </RadioGroup>
      </Field>
      <p className="text-sm text-muted-foreground">
        value: <code>{value}</code>
      </p>
    </div>
  );
}

