const InvalidSource = "import { RadioGroupInvalid } from \"../examples/upstream/radio-group-invalid\";\n\nconst Example = () => <RadioGroupInvalid />;\n\nexport default Example;\n";

const meta = {
  component: RadioGroup,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "A set of checkable buttons—known as radio buttons—where no more than one of the buttons can be checked at a time.\n\n**Import:** `@/registry/erbium/ui/radio-group`\n\n## Usage\n\n```tsx\nimport { Field, FieldLabel } from \"@/registry/erbium/ui/field\";\nimport { RadioGroup, RadioGroupItem } from \"@/registry/erbium/ui/radio-group\";\n```\n\n```tsx\n<RadioGroup defaultValue=\"option-one\">\n  <Field orientation=\"horizontal\">\n    <RadioGroupItem value=\"option-one\" id=\"option-one\" />\n    <FieldLabel htmlFor=\"option-one\">Option One</FieldLabel>\n  </Field>\n  <Field orientation=\"horizontal\">\n    <RadioGroupItem value=\"option-two\" id=\"option-two\" />\n    <FieldLabel htmlFor=\"option-two\">Option Two</FieldLabel>\n  </Field>\n</RadioGroup>\n```\n\n## Composition\n\nUse the following composition to build a `RadioGroup`:\n\n```text\nRadioGroup\n├── RadioGroupItem\n└── RadioGroupItem\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Radio Group](https://base-ui.com/react/components/radio-group)",
      },
    },
  },
} satisfies Meta<typeof RadioGroup>;

export default { ...meta, title: "Inputs & forms/Radio Group",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

